import React, { useMemo, useState } from 'react';
import { useParams, useLocation, Link } from 'react-router-dom';
import { useShop } from '../context/ShopContext';
import { ExtendedShopProduct, IMAGES } from '../constants';
import { ShoppingBag, Star, CheckCircle2, Search, Heart, Scale, SlidersHorizontal } from 'lucide-react';
import ResponsiveStoreImage from '../components/ResponsiveStoreImage';

type SortOption = 'featured' | 'price-asc' | 'price-desc' | 'rating';

const ShopCategory: React.FC = () => {
  const { category: paramCategory } = useParams<{ category?: string }>();
  const location = useLocation();
  const {
    storeInventory,
    courses,
    bundles,
    subscriptions,
    allCatalogItems,
    addToCart,
    formatPrice,
    isSaved,
    toggleSaved,
    compareIds,
    toggleCompare,
    isLoading,
    refreshAll,
  } = useShop();

  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('featured');

  // Resolve category from either URL params (/shop/:category) or top-level path (/courses, /products, etc.)
  const activeCategory = useMemo(() => {
    if (paramCategory) return paramCategory.toLowerCase();
    const seg = location.pathname.split('/').filter(Boolean)[0];
    return seg ? seg.toLowerCase() : 'products';
  }, [paramCategory, location.pathname]);

  const categoryMeta: Record<string, { kicker: string; title: string; subtitle: string }> = {
    products: {
      kicker: 'Commercial Software · Source Code Included',
      title: 'Digital Systems & Trading Engines',
      subtitle: 'Institutional MetaTrader 5 order-flow tools, multi-tenant SaaS starter kits, headless e-commerce systems, and kinetic UI libraries.'
    },
    courses: {
      kicker: 'Structured Engineering Curriculum · Video + Repositories',
      title: 'Engineering Masterclasses',
      subtitle: 'In-depth technical courses covering MQL5 execution architecture, WebSocket telemetry bridges, and full-stack web engineering.'
    },
    bundles: {
      kicker: 'Complete Studio Suites · Multi-System Licensing',
      title: 'Architectural Bundles',
      subtitle: 'Curated combinations of our commercial software engines, SaaS boilerplates, and engineering masterclasses at bundled studio pricing.'
    },
    subscriptions: {
      kicker: 'Continuous Access · Commercial Seat Allocation',
      title: 'Studio & Institutional Plans',
      subtitle: 'Recurring memberships for quantitative desks, software agencies, and independent developers requiring continuous updates and multi-seat licensing.'
    }
  };

  const meta = categoryMeta[activeCategory] || categoryMeta.products;

  const items: ExtendedShopProduct[] = useMemo(() => {
    let base: ExtendedShopProduct[] = [];
    if (activeCategory === 'products') base = storeInventory as ExtendedShopProduct[];
    else if (activeCategory === 'courses') base = courses as ExtendedShopProduct[];
    else if (activeCategory === 'bundles') base = bundles as ExtendedShopProduct[];
    else base = allCatalogItems as ExtendedShopProduct[];

    const filtered = !searchQuery.trim()
      ? base
      : base.filter(
          item =>
            item.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            item.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
            item.tags?.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()))
        );

    if (sortBy === 'price-asc') return [...filtered].sort((a, b) => a.price - b.price);
    if (sortBy === 'price-desc') return [...filtered].sort((a, b) => b.price - a.price);
    if (sortBy === 'rating') return [...filtered].sort((a, b) => b.rating - a.rating);
    return filtered;
  }, [activeCategory, storeInventory, courses, bundles, allCatalogItems, searchQuery, sortBy]);

  return (
    <div className="min-h-screen bg-[#FBFBF9] dark:bg-[#090A0D] pt-28 pb-24 transition-colors duration-200">
      <div className="max-w-[1360px] mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* Category Header */}
        <div className="pb-12 mb-12 border-b border-[#E4E4DE] dark:border-[#222630] flex flex-col lg:flex-row lg:items-end justify-between gap-8">
          <div className="max-w-2xl">
            <div className="text-xs text-emerald-700 dark:text-emerald-400 font-medium mb-2">
              {meta.kicker}
            </div>
            <h1 className="font-display text-3xl sm:text-5xl font-extrabold text-slate-900 dark:text-white tracking-tight mb-4">
              {meta.title}
            </h1>
            <p className="text-base text-slate-600 dark:text-slate-400 leading-relaxed">
              {meta.subtitle}
            </p>
          </div>

          {/* Category Quick Switcher + Search + Sort */}
          <div className="flex flex-col sm:flex-row flex-wrap items-stretch sm:items-center gap-3">
            {activeCategory !== 'subscriptions' && (
              <>
                <div className="relative">
                  <Search size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    type="text"
                    value={searchQuery}
                    onChange={e => setSearchQuery(e.target.value)}
                    placeholder={`Search ${activeCategory}...`}
                    className="h-10 pl-9 pr-4 rounded-lg bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] text-xs text-slate-900 dark:text-white placeholder-slate-400 focus:outline-none focus:border-emerald-600 w-full sm:w-52"
                  />
                </div>
                <div className="relative">
                  <SlidersHorizontal size={13} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                  <label htmlFor="category-sort-select" className="sr-only">Sort items</label>
                  <select
                    id="category-sort-select"
                    name="category-sort-select"
                    value={sortBy}
                    onChange={e => setSortBy(e.target.value as SortOption)}
                    aria-label="Sort items"
                    className="h-10 pl-8 pr-4 rounded-lg bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] text-xs font-medium text-slate-700 dark:text-slate-300 focus:outline-none focus:border-emerald-600 cursor-pointer"
                  >
                    <option value="featured">Sort: Featured</option>
                    <option value="price-asc">Price: Low to High</option>
                    <option value="price-desc">Price: High to Low</option>
                    <option value="rating">Highest Rated</option>
                  </select>
                </div>
              </>
            )}

            <div className="flex items-center gap-1 p-1 bg-[#F3F3EE] dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] rounded-lg">
              {[
                { label: 'Products', path: '/products', key: 'products' },
                { label: 'Courses', path: '/courses', key: 'courses' },
                { label: 'Bundles', path: '/bundles', key: 'bundles' },
                { label: 'Plans', path: '/subscriptions', key: 'subscriptions' }
              ].map(tab => (
                <Link
                  key={tab.key}
                  to={tab.path}
                  className={`px-3 py-1.5 rounded-md text-xs font-semibold transition-colors whitespace-nowrap ${
                    activeCategory === tab.key
                      ? 'bg-white dark:bg-[#171A21] text-slate-900 dark:text-white shadow-xs'
                      : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'
                  }`}
                >
                  {tab.label}
                </Link>
              ))}
            </div>
          </div>
        </div>

        {/* Subscriptions View */}
        {activeCategory === 'subscriptions' ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 max-w-5xl mx-auto">
            {subscriptions.map((plan: any) => (
              <div
                key={plan.id}
                className={`bg-white dark:bg-[#111318] rounded-2xl p-8 sm:p-10 border flex flex-col justify-between ${
                  plan.recommended
                    ? 'border-emerald-600 dark:border-emerald-500'
                    : 'border-[#E4E4DE] dark:border-[#222630]'
                }`}
              >
                <div>
                  <div className="flex items-center justify-between gap-2 text-xs mb-3">
                    <span className="text-slate-500 dark:text-slate-400 font-medium">
                      Commercial Membership
                    </span>
                    {plan.recommended && (
                      <span className="text-emerald-600 dark:text-emerald-400 font-semibold">
                        Recommended Tier
                      </span>
                    )}
                  </div>

                  <h2 className="font-display text-2xl font-bold text-slate-900 dark:text-white mb-2">
                    {plan.name}
                  </h2>
                  <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed mb-6">
                    {plan.description || 'Full studio access to updated engineering tools and commercial seat licenses.'}
                  </p>

                  <div className="flex items-baseline gap-1 pb-6 mb-6 border-b border-[#E4E4DE] dark:border-[#222630] font-mono tabular-nums">
                    <span className="text-4xl font-bold text-slate-900 dark:text-white">
                      {formatPrice(plan.price)}
                    </span>
                    <span className="text-xs text-slate-500 dark:text-slate-400">
                      {plan.period || '/month'}
                    </span>
                  </div>

                  <div className="space-y-3.5 mb-8">
                    {(plan.features || []).map((feat: string, i: number) => (
                      <div key={i} className="flex items-start gap-3 text-sm text-slate-700 dark:text-slate-300">
                        <CheckCircle2 size={16} className="text-emerald-600 dark:text-emerald-400 shrink-0 mt-0.5" />
                        <span>{feat}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <button
                  type="button"
                  onClick={() =>
                    addToCart({
                      id: plan.id,
                      title: plan.name,
                      price: plan.price,
                      type: 'subscription',
                      image: IMAGES.heroShowcase,
                      rating: 5.0,
                      reviews: 24,
                      tags: ['Subscription', 'Commercial License'],
                      description: plan.description || 'Studio Membership Plan',
                      features: plan.features || []
                    })
                  }
                  className={`w-full py-3.5 px-6 rounded-lg text-xs font-semibold transition-colors flex items-center justify-center gap-2 ${
                    plan.recommended
                      ? 'bg-emerald-600 hover:bg-emerald-500 text-white'
                      : 'bg-slate-900 dark:bg-white text-white dark:text-slate-950 hover:opacity-90'
                  }`}
                >
                  <ShoppingBag size={14} />
                  <span>Select Membership Plan</span>
                </button>
              </div>
            ))}
          </div>
        ) : isLoading && items.length === 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {[1, 2, 3].map(n => (
              <div
                key={n}
                className="bg-white dark:bg-[#111318] rounded-2xl overflow-hidden border border-[#E4E4DE] dark:border-[#222630] p-6 space-y-4 animate-pulse"
              >
                <div className="aspect-[4/3] w-full bg-slate-200 dark:bg-[#1c202a] rounded-xl" />
                <div className="h-4 bg-slate-200 dark:bg-[#1c202a] rounded w-3/4" />
                <div className="h-3 bg-slate-200 dark:bg-[#1c202a] rounded w-1/2" />
                <div className="h-8 bg-slate-200 dark:bg-[#1c202a] rounded mt-4" />
              </div>
            ))}
          </div>
        ) : items.length === 0 ? (
          <div className="py-20 text-center bg-white dark:bg-[#111318] rounded-2xl border border-[#E4E4DE] dark:border-[#222630]">
            <p className="text-sm text-slate-500 mb-4">No releases currently found in this category on the server.</p>
            <div className="flex items-center justify-center gap-3">
              <button
                type="button"
                onClick={() => refreshAll()}
                className="px-4 py-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg text-xs font-semibold transition-colors"
              >
                Refresh Category
              </button>
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery('')}
                  className="px-4 py-2 bg-slate-900 dark:bg-white text-white dark:text-slate-950 rounded-lg text-xs font-semibold"
                >
                  Clear Search
                </button>
              )}
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {items.map(product => {
              const saved = isSaved(product.id);
              const inCompare = compareIds.includes(product.id);

              return (
                <article
                  key={product.id}
                  className="group bg-white dark:bg-[#111318] rounded-2xl overflow-hidden border border-[#E4E4DE] dark:border-[#222630] hover:border-slate-400 dark:hover:border-slate-700 transition-all duration-200 hover:-translate-y-0.5 flex flex-col"
                >
                  <div className="relative aspect-[4/3] overflow-hidden bg-[#F3F3EE] dark:bg-[#171A21] border-b border-[#E4E4DE] dark:border-[#222630]">
                    <Link to={`/item/${product.id}`} className="block w-full h-full">
                      <ResponsiveStoreImage
                        src={product.image}
                        alt={product.title}
                        sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 403px"
                        width={403}
                        height={302}
                        className="w-full h-full object-cover group-hover:scale-[1.03] transition-transform duration-300"
                      />
                    </Link>

                    {/* Top-right Save & Compare Actions */}
                    <div className="absolute top-3 right-3 flex items-center gap-1.5">
                      <button
                        type="button"
                        onClick={() => toggleCompare(product.id)}
                        title="Compare specifications"
                        className={`w-8 h-8 rounded-lg border flex items-center justify-center transition-colors backdrop-blur-md ${
                          inCompare
                            ? 'bg-emerald-600 border-emerald-500 text-white'
                            : 'bg-white/90 dark:bg-[#090A0D]/85 border-[#E4E4DE] dark:border-[#222630] text-slate-700 dark:text-slate-300 hover:text-emerald-600'
                        }`}
                      >
                        <Scale size={14} />
                      </button>
                      <button
                        type="button"
                        onClick={() => toggleSaved(product.id)}
                        title={saved ? 'Remove from saved' : 'Save system'}
                        className={`w-8 h-8 rounded-lg border flex items-center justify-center transition-colors backdrop-blur-md ${
                          saved
                            ? 'bg-rose-500 border-rose-500 text-white'
                            : 'bg-white/90 dark:bg-[#090A0D]/85 border-[#E4E4DE] dark:border-[#222630] text-slate-700 dark:text-slate-300 hover:text-rose-500'
                        }`}
                      >
                        <Heart size={14} fill={saved ? 'currentColor' : 'none'} />
                      </button>
                    </div>
                  </div>

                  <div className="p-6 flex-1 flex flex-col">
                    <div className="flex items-center justify-between gap-2 text-xs text-slate-500 dark:text-slate-400 mb-2">
                      <div className="flex items-center gap-1.5 truncate">
                        <span className="capitalize font-medium text-slate-700 dark:text-slate-300">
                          {product.type === 'digital' ? 'Software System' : product.type}
                        </span>
                        {product.version && (
                          <>
                            <span aria-hidden="true">·</span>
                            <span className="font-mono">{product.version}</span>
                          </>
                        )}
                      </div>
                      <div className="flex items-center gap-1 font-mono tabular-nums shrink-0">
                        <Star size={12} className="text-amber-500 fill-amber-500" />
                        <span className="font-semibold text-slate-800 dark:text-slate-200">{product.rating.toFixed(1)}</span>
                      </div>
                    </div>

                    <Link
                      to={`/item/${product.id}`}
                      className="font-display text-lg font-bold text-slate-900 dark:text-white group-hover:text-emerald-600 dark:group-hover:text-emerald-400 transition-colors line-clamp-1 mb-2"
                    >
                      {product.title}
                    </Link>

                    <p className="text-sm text-slate-600 dark:text-slate-400 line-clamp-2 leading-relaxed mb-5">
                      {product.description}
                    </p>

                    <div className="mt-auto pt-4 border-t border-[#E4E4DE] dark:border-[#222630] flex items-center justify-between gap-3">
                      <div className="font-mono tabular-nums">
                        <div className="flex items-baseline gap-2">
                          <span className="text-xl font-bold text-slate-900 dark:text-white">
                            {formatPrice(product.price)}
                          </span>
                          {product.originalPrice && (
                            <span className="text-xs text-slate-400 line-through">
                              {formatPrice(product.originalPrice)}
                            </span>
                          )}
                        </div>
                        <div className="text-[11px] text-slate-500 font-sans">
                          {product.licenseScope || 'Source + Commercial License'}
                        </div>
                      </div>

                      <div className="flex items-center gap-2">
                        <Link
                          to={`/item/${product.id}`}
                          className="px-3 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] text-xs font-semibold text-slate-700 dark:text-slate-300 hover:bg-[#F3F3EE] dark:hover:bg-[#171A21] transition-colors"
                        >
                          Specs
                        </Link>
                        <button
                          type="button"
                          onClick={() => addToCart(product)}
                          className="px-3.5 py-2 rounded-lg bg-slate-900 dark:bg-white text-white dark:text-slate-950 hover:bg-emerald-600 dark:hover:bg-emerald-400 dark:hover:text-slate-950 text-xs font-semibold transition-colors inline-flex items-center gap-1.5"
                        >
                          <ShoppingBag size={13} />
                          <span>Add</span>
                        </button>
                      </div>
                    </div>
                  </div>
                </article>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default ShopCategory;
